            float coeffthresh_basedon_bounding_box_side(const tc::point_f& image_center, const tc::rect_i& target) 
            {
                auto[cx, cy] = image_center;
                auto[xmax, ymax] = target.br();
                auto[xmin, min] = target.tl()

                const auto lowThreshCoeff = 0.25f;
                const auto higThreshCoeff = 0.5f;

                // top left
                if (xmin < cx && xmax < cx && ymin < cy && ymax < cy) {
                    return lowThreshCoeff;
                }
                // left
                else if (xmax < cx && ymin < cy && ymax > cy) {
                    return higThreshCoeff;
                }
                // bottom-left
                else if (xmin < cx && xmax < cx && ymin > cy && ymax > cy) {
                    return lowThreshCoeff;
                }
                // top
                else if (ymax < cy && xmin < cx && xmax > cx) {
                    return lowThreshCoeff;
                }
                // bottom 
                else if (ymin > cy && xmin < cx && xmax > cx) {
                    return lowThreshCoeff;
                }
                // top right
                else if (xmin > cx && xmax > cx && ymax < cy) {
                    return lowThreshCoeff;
                }
                // right
                else if (xmin > cx && ymin < cy && ymax > cy) {
                    return higThreshCoeff;
                }
                // bottom-right
                else if (xmin > cx && xmax > cx && ymin > cy) {
                    return lowThreshCoeff;
                }
                // centered
                else {
                    return higThreshCoeff;
                }
            }

